def transform(grid):
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]

    # The 5 marks the starting position in the output panel.
    mr = mc = 0
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 5:
                mr, mc = r, c - 8
                out[mr][mc] = 5

    # Read the 3x3 tiles down the left group, then down the right group.
    tiles = []
    for left in (0, 4):
        for top in range(0, h - 2, 4):
            color = next(
                (grid[r][c] for r in range(top, top + 3)
                 for c in range(left, left + 3) if grid[r][c] != 0),
                0
            )
            if color:
                tiles.append(color)

    y, x = mr, mc
    for color in tiles:
        if color == 6:
            # Downward stroke, two cells long.
            for _ in range(2):
                y += 1
                if 0 <= y < h and 0 <= x < 7:
                    out[y][x] = color
        else:
            length, direction = {
                1: (3, 1),   # east
                2: (2, -1),  # west
                3: (4, -1),  # west
            }[color]
            y += 1
            for _ in range(length):
                if 0 <= y < h and 0 <= x < 7:
                    out[y][x] = color
                x += direction
            x -= direction

    return out
